    allowanceUnpaidDesc: 'पोस्ट पब्लिश झाली. न भरलेली रक्कम तुमच्या खात्याविरूद्ध खुली राहते आणि ती निकाली निघेपर्यंत तुमची पुढील पेड पोस्ट अवरोधित करते — परंतु कधीही विनामूल्य नाही. उद्याचे भत्ता तुम्हाला जे काही देईल ते नेहमीच तुमचे असेल, काहीही थकबाकी असो किंवा नसो.',
