    allowanceCounts2: 'व्हिडिओ, प्रतिमा आणि ऑडिओ पोस्ट्स डेटा भत्ता — लघुप्रतिमा समाविष्ट करण्याच्या विरूद्ध त्यांचे फाइल आकार खर्च करतात, कारण त्या देखील संग्रहित आणि दिल्या जातात.',
