    allowanceBadgeNote: 'एक बॅज एकाच वेळी दोन्ही अर्धवट हलवते — एक मोठा विनामूल्य भत्ता आणि त्यापूर्वीच्या कोणत्याही गोष्टीवर कमी किंमत. डेहब टोकन खरेदी करताना सवलत समान शिडी बॅज धारकांना आधीपासूनच मिळते, क्रॅब येथे 5% ते मेगालोडॉनमध्ये 30% पर्यंत, म्हणून बॅजचे मूल्य काय आहे याचे एक उत्तर आहे. तुमचा भत्ता तुम्ही कमावलेल्या बिल्लावरून मिळतो: समर्थकाने तुम्हाला दिलेला स्तर तुमच्या प्रोफाइलवर दाखवतो, परंतु तो तुम्हाला त्यांचा पोस्टिंग भत्ता देत नाही.',
