    superPowersTitle: 'सुपरपॉवर्स',
    superPowersDesc: 'सुपरपॉवर्स स्टॅकिंग बॅजला तुम्ही खर्च करू शकता. प्रत्येक पंधरवड्यात आपल्या बॅज अनुदान वाढते, आणि एक खर्च मुख्यपृष्ठ फीड शीर्षस्थानी स्लॉट मध्ये एक पोस्ट ठेवते. टीम अप प्रत्येकासाठी खुले आहे आणि आठ खात्यांची वॉलेट पॉवर एकत्र करते, ज्यामुळे प्रत्येक सदस्याला त्यांचे एकूण अनलॉक मिळतात. स्लॉट फिरतो: जेव्हा अनेक बूस्ट्स चालू असतात, तेव्हा दर्शकांना बॅज स्तरानुसार वजन दिले जाते, म्हणून उच्च स्तर अधिक वेळा दर्शविला जातो आणि प्रत्येकाला त्यांना दिलेली विंडो मिळते.',
    superPowersDescV2: 'सुपरपॉवर्स स्टॅकिंग बॅजला तुम्ही खर्च करू शकता. प्रत्येक पंधरवड्यात आपल्या बॅज अनुदान वाढते, आणि एक खर्च मुख्यपृष्ठ फीड शीर्षस्थानी स्लॉट मध्ये एक पोस्ट ठेवते. टीम अप प्रत्येकासाठी खुले आहे आणि आठ खात्यांची वॉलेट पॉवर एकत्र करते, ज्यामुळे प्रत्येक सदस्याला त्यांचे एकूण अनलॉक मिळतात. स्लॉट फिरतो: जेव्हा अनेक बूस्ट्स चालू असतात, तेव्हा दर्शकांना बॅज स्तरानुसार वजन दिले जाते, म्हणून उच्च स्तर अधिक वेळा दर्शविला जातो आणि प्रत्येकाला त्यांना दिलेली विंडो मिळते.',
    boostPower: '1) बूस्ट',
    boostPowerDesc: 'मागील आठवड्यातील एक पोस्ट आपल्या घराच्या मुख्यपृष्ठावरील अन्नपदार्थांच्या शीर्षस्थानी ठेवा. क्रॅब येथे अनलॉक होते. आता थेट.',
    secondWindPower: '2) दुसरा वारा',
    secondWindPowerDesc: 'एका आठवड्यापेक्षा जास्त जुन्या पोस्टला फीडच्या शीर्षस्थानी परत पाठवा. घोस्ट लॉबस्टर येथे अनलॉक होते. आता थेट.',
    trendJacker: '4) ट्रेंड जॅकर',
    trendJackerDesc2: 'ट्रेंडिंग यादीच्या शीर्षस्थानी आपल्या श्रेणींपैकी एक ठेवा. राक्षस कासव येथे अनलॉक. आता थेट.',
    timelineBomber: '5) टाइमलाइन बॉम्बर',
    timelineBomberDesc2: 'आपले अनुयायी इतर कोणाच्याही बूस्टच्या पुढे आपले पोस्ट पाहतात — एक किंग कोब्रा आपल्याकडून ऐकणे निवडलेल्या लोकांसाठी एक मेगालोडॉन मारतो. किंग कोब्रा येथे अनलॉक होते. आता थेट.',
    precisionStrike: '8) प्रिसिजन स्ट्राइक',
    precisionStrikeDesc: 'तुमच्या नावावर असलेल्या खात्याचे अनुसरण करणार्या लोकांपर्यंत पोहोचा. डॉल्फिनवर अनलॉक होते. आता लाइव्ह करा.',
    harpoon: '9) हार्पून',
    harpoonDesc: 'तुम्ही एका पोस्टबद्दल निवडलेल्या बॅज स्तरातील प्रत्येक धारकाला सूचित करा. टायगर शार्क येथे अनलॉक करते. आता जिवंत रहा.',
    superPowersMore2: 'या अॅपमध्ये सर्व 12 पॉवर्स लाइव्ह आणि लिस्टेड आहेत. इतर कोणाच्या थ्रेडच्या शीर्षस्थानी अँकरने आपली टिप्पणी ठेवली आहे. सिग्नल फ्लेअर तुम्हाला फॉलो करणाऱ्या प्रत्येक खात्यावर एक सूचना पाठवते. फ्लॅक जॅकेट धावत असताना डाउनवोट दफन करण्यासाठी पोस्ट रोगप्रतिकारक बनवते. टीम अप तब्बल आठ खाती त्यांची वॉलेट पॉवर एकत्र करू देते, म्हणून प्रत्येक सदस्याने त्यांची पूल केलेली शिल्लक अनलॉक केलेली बॅज घातली आहे. पुढील पंक्ती आपण होस्ट करीत असलेल्या स्टेजला स्टेज रेल्वेच्या शीर्षस्थानी ठेवते. गहन वर्तमान आपल्या एखाद्याच्या पोस्टला दुसर्याच्या पोस्टला बूस्ट देते.',
    superPowersMoreV2: 'या अॅपमध्ये सर्व 12 पॉवर्स लाइव्ह आणि लिस्टेड आहेत. इतर कोणाच्या थ्रेडच्या शीर्षस्थानी अँकरने आपली टिप्पणी ठेवली आहे. सिग्नल फ्लेअर तुम्हाला फॉलो करणाऱ्या प्रत्येक खात्यावर एक सूचना पाठवते. फ्लॅक जॅकेट धावत असताना डाउनवोट दफन करण्यासाठी पोस्ट रोगप्रतिकारक बनवते. टीम अप तब्बल आठ खाती त्यांची वॉलेट पॉवर एकत्र करू देते, म्हणून प्रत्येक सदस्याने त्यांची पूल केलेली शिल्लक अनलॉक केलेली बॅज घातली आहे. पुढील पंक्ती आपण होस्ट करीत असलेल्या स्टेजला स्टेज रेल्वेच्या शीर्षस्थानी ठेवते. गहन वर्तमान आपल्या एखाद्याच्या पोस्टला दुसर्याच्या पोस्टला बूस्ट देते.',
