    spRotationDesc: 'पिंपरी - चिंचवड ऐवजी पिंपरी चिंचवडला. जेव्हा एकाच वेळी अनेक बूस्ट चालू असतात, तेव्हा प्रत्येक दर्शकास बूस्टरच्या बॅज स्तराने वजन दिले जाते — एक उच्च स्तर अधिक वेळा दर्शविला जातो आणि तरीही प्रत्येकाला त्यांनी दिलेली खिडकी मिळते. काय बूस्ट खरेदी करते हे काही मिनिटांसाठी आवाजाचा एक वाटा आहे, केवळ फीडच्या शीर्षस्थानी नाही.',
