    altCommandCentre: 'कमांड सेंटर, आय आणि लेनदेनसाठी निर्मित करणारा फायनान्स डॅशबोर्ड.',
    altBounties: 'बाउंटीज बोर्ड, जे कॅटेगरी आणि मुद्रावरून फिल्टर केले जाऊ शकते, आणि "बाउंटी पोस्ट करा" असेल.',
    altStores: 'स्टोर्स पेज, जिथे क्रिएटर्स आणि व्यवसायांचे स्वतःचे स्टोरफ्रंट चालतात.',
    altAssistant: 'AI सहाय्यक, प्रत्येक खात्याशी अ‍ॅपमध्ये उपलब्ध आहे.',
    altAds: 'मोहीम तयार करण्यासाठी आणि वित्तपुरवठा करण्यासाठी स्वयं - सेवा जाहिरात पोर्टल.',
    altConnect: 'The Connect page, DeHub व ChatGPT किंवा Claude यांना MCP वर जोडण्यासाठी.',
    altArchitecture: 'विकेंद्रीकृत स्ट्रीमिंग ॲप आर्किटेक्चर',
    altFeatures: 'फीचर रिक्वेस्ट बोर्ड, जिथे समुदाय कल्पना सबमिट करतो आणि त्यावर मतदान करतो.',
    cinemaDesc: 'dehub.io/cinema वरील सिनेमा हे चित्रपट आणि मालिकांसाठी \'कुठे पाहावे\' हे शोधण्याचे ठिकाण आहे. एखादे शीर्षक शोधा आणि ते तुमच्या देशात पाहण्याचे सर्व कायदेशीर मार्ग शोधा — कोणत्या सेवांवर ते स्ट्रीम होते, भाड्याने घेण्याची किंमत काय आहे आणि विकत घेण्याची किंमत काय आहे. प्रत्येक चित्रपट आणि मालिकेचे स्वतःचे पेज असेल, ज्यावर शेअर कार्ड असेल आणि समुदाय त्यावर पुनरावलोकन करू शकेल.',
    communitiesB2Desc: 'प्रत्येक समुदायासाठी एक समर्पित फीड आणि चॅट असेल जिथे सदस्य पोस्ट करू शकतील, चर्चा करू शकतील, मतदान करू शकतील, एकमेकांना @mention करू शकतील आणि टिप देऊ शकतील, ज्याचे व्यवस्थापन समुदाय मालक करेल.',
    daoB1Desc: 'तुमच्या वॉलेटमधून \'Contribute\' बटण वापरून DeHub टोकन पाठवा. तुम्ही जोडलेले प्रत्येक टोकन तुमचा हिस्सा वाढवते.',
    daoTitle: 'DAO ट्रेझरी',
    kidsB1Desc: 'सेटिंग्जमध्ये ते चालू करा आणि चार ते आठ अंकी पिन निवडा. ते पुन्हा बंद करण्यासाठी तोच पिन आवश्यक असेल आणि चुकीचा पिन डिव्हाइस अनलॉक करू शकणार नाही.',
    miniAppsB3: 'एक तयार करा:',
    miniAppsB3Desc: 'कोणतीही वेबसाइट एका स्क्रिप्ट टॅगसह मिनी ॲप बनते. dehub.io/apps/dev तुमचा मॅनिफेस्ट तपासतो, तुमच्या फीड कार्डचे पूर्वावलोकन करतो आणि इतरांना दिसण्यापूर्वी DeHub मध्ये ॲप चालवतो. Farcaster मिनी ॲप्स जसे आहेत तसे काम करतात.',
    msg11: 'ऑप्ट-इन ऑनलाइन स्टेटस: तुम्ही शेअर करण्याचा निर्णय घेतल्यासच हिरवा ठिपका दिसेल.',
    packsB1Desc: 'इमोजी, स्टिकर किंवा GIF पॅक तयार करण्यासाठी प्रतिमा अपलोड करा किंवा लिंक्स पेस्ट करा. उच्च बॅज टियरला अधिक पॅक मिळतात आणि प्रत्येक पॅकमध्ये अधिक जागा मिळते.',
    packsDesc: 'इमोजी पिकरमध्ये शोध, त्वचेचे रंग आणि अलीकडील इमोजीसह प्रत्येक इमोजी असतो आणि इतर ॲप्समधील इमोजी इनलाइन रेंडर होतात. याव्यतिरिक्त, बॅज धारक स्वतःचे इमोजी, स्टिकर आणि GIF पॅक तयार करतात आणि कोणीही सामायिक पॅक त्यांच्या पिकरमध्ये जोडू शकतो आणि चॅट्स, टिप्पण्या आणि प्रतिक्रियांमध्ये वापरू शकतो.',
    packsTitle: 'इमोजी, स्टिकर्स आणि पॅक्स',
    tocDao: 'DAO ट्रेझरी',
    useCase5: 'कोणती सामग्री यशस्वी होईल याचा अंदाज लावा',
    walletHubB3Desc: 'DeHub Pay द्वारे ॲपमध्ये टॉप अप करा, कार्डद्वारे किंवा $0.50 पासून दुसऱ्या चेनवरील क्रिप्टोने.',
    walletHubB5: 'सोलाना:',
