    howItWorksDesc2: 'होल्डिंग आणि स्टेकिंगमुळे ॲप तुमच्यासाठी कसे वागते हे देखील बदलते. आपण जितके अधिक डीहब टोकन धारण कराल तितके आपले प्लॅटफॉर्म शुल्क कमी होईल आणि आपण अधिक क्षमता अनलॉक कराल — बॅजेस, पडताळणी, ट्रेंड बूस्ट्स, क्लब स्तर आणि नेटवर्कमध्ये वर्धित अधिकार. सराव मध्ये चलन एक बोल्ट - ऑन नाहीः तो परवानगी थर, बक्षीस रेल्वे आणि चेकआउट एकाच वेळी आहे.',
