    profitShareTitle: 'नफा वाटा',
    profitShareDesc1: 'डेहब डिझाइन केलेले आहे जेणेकरुन नेटवर्क वापरणार्या लोकांकडे ते असेल. प्रोटोकॉल महसूल — प्लॅटफॉर्म फी, स्टोअर आणि मार्केटप्लेस फी, जाहिरात, एआय वापर आणि गेम महसूल — ताजे मिंट केलेल्या पुरवठ्याऐवजी वास्तविक उत्पन्न वितरण आणि खरेदी - बॅकच्या रूपात भाग घेणार्या धारकांकडे परत जाते. DeHub टोकन मालकी म्हणून DeHub नेटवर्क स्वतः एक हिस्सा मालकी आहे, फक्त एक खर्च शिल्लक नाही.',
    profitShareDesc2: 'प्रोटोकॉल प्रत्यक्षात जे कमावते त्यातून वितरकांना वित्तपुरवठा केला जातो, व्हेरिएबल मध्यांतरांवर, आणि स्टेक केलेल्या रकमेनुसार आणि कालावधीनुसार स्टेकिंग स्तरांमध्ये विभाजित केले जाते. दीर्घ प्रतिबद्धतेमुळे प्रत्येक वितरणाचा मोठा हिस्सा मिळतो. स्तर यांत्रिकीसाठी स्टेक आणि रिवॉर्डची अचूक गणना पहा.',
    pegTitle: 'PEGED किंमत आणि DEX सूची',
    pegDesc1: 'डेहब टोकन एक उपयुक्त टोकन आहे. ॲप - मधील हेतूंसाठी ते सध्या प्रति टोकन $ 0.001 आहे, जो फियाट गेटवेद्वारे खरेदी करताना तुम्हाला दिसणारा दर आणि ॲप - मधील किंमतीसाठी वापरलेला दर आहे. नेटवर्क स्केल होत असताना अॅप - मधील अर्थव्यवस्था स्थिर आणि अंदाज करण्यायोग्य ठेवण्यासाठी ते पीईजी अस्तित्त्वात आहे — हा एक अंतर्गत लेखा दर आहे, भविष्यातील मूल्याचा मजला, हमी किंवा वचन नाही.',
    pegDesc2: 'विकेंद्रित एक्सचेंजवर टोकन व्यवहार, तरलता पूल एकाधिक साखळ्या ओलांडून त्याच 0.001 बेस किंमतीतून बियाणे. खुल्या बाजारात किंमत ट्रेडिंगद्वारे सेट केली जाते - डीहबद्वारे नाही — याचा अर्थ डेहब टोकन कोणत्याही वेळी अॅप - मधील पेगच्या वर किंवा खाली व्यापार करू शकतात. डेहब आपली अधिकृत तरलता डीएक्सवर बीजित करते जेणेकरून प्रत्येक व्यवहार सार्वजनिकपणे चेनवर पडताळणीयोग्य राहील.',
